import * as React from 'react';
import Typography from '@mui/material/Typography';
import Box from '@mui/material/Box';
import Container from '@mui/material/Container';
import Grid from '@mui/material/Grid';
import Card from '@mui/material/Card';
import CardContent from '@mui/material/CardContent';
import CardMedia from '@mui/material/CardMedia';
import Chip from '@mui/material/Chip';
import Stack from '@mui/material/Stack';

// Portfolio items data
const portfolioItems = [
  {
    id: 1,
    image: '/img/portfolio/project1.jpg',
    title: 'E-Commerce Platform',
    tags: ['UI/UX', 'Web Development', 'React'],
    description: 'A modern e-commerce solution with seamless user experience and robust backend integration.'
  },
  {
    id: 2,
    image: '/img/portfolio/project2.jpg',
    title: 'Healthcare App',
    tags: ['Mobile App', 'UI/UX', 'Flutter'],
    description: 'Patient-centric healthcare application focusing on appointment management and health tracking.'
  },
  {
    id: 3,
    image: '/img/portfolio/project3.jpg',
    title: 'Brand Identity',
    tags: ['Branding', 'Design', 'Marketing'],
    description: 'Complete brand identity redesign for a leading tech startup.'
  },
  {
    id: 4,
    image: '/img/portfolio/project4.jpg',
    title: 'Analytics Dashboard',
    tags: ['Web Development', 'Data Visualization', 'React'],
    description: 'Real-time analytics dashboard with interactive data visualization.'
  },
  // Add more items as needed
];

export default function Portfolio() {
  return (
    <Box
      id="portfolio"
      sx={{
        pt: { xs: 4, sm: 12 },
        pb: { xs: 8, sm: 16 },
      }}
    >
      <Container maxWidth="lg">
        <Typography 
          component="h1" 
          variant="h2" 
          align="center"
          sx={{
            color: 'primary.main',
            mb: 8
          }}
        >
          Putting Our Best Foot Forward
        </Typography>

        <Grid container spacing={4}>
          {portfolioItems.map((item) => (
            <Grid item xs={12} sm={6} md={3} key={item.id}>
              <Card
                sx={{
                  height: '100%',
                  display: 'flex',
                  flexDirection: 'column',
                  backgroundColor: '#0C2645',
                  transition: 'transform 0.3s ease-in-out',
                  '&:hover': {
                    transform: 'translateY(-8px)',
                  },
                }}
              >
                <CardMedia
                  component="img"
                  height="200"
                  image={item.image}
                  alt={item.title}
                  sx={{
                    objectFit: 'cover',
                  }}
                />
                <CardContent sx={{ flexGrow: 1 }}>
                  <Typography 
                    gutterBottom 
                    variant="h5" 
                    component="h2"
                    sx={{ 
                      color: 'primary.main',
                      mb: 2
                    }}
                  >
                    {item.title}
                  </Typography>
                  
                  <Stack direction="row" spacing={1} sx={{ mb: 2, flexWrap: 'wrap', gap: 1 }}>
                    {item.tags.map((tag, index) => (
                      <Chip
                        key={index}
                        label={tag}
                        size="small"
                        sx={{
                          backgroundColor: 'rgba(96, 166, 231, 0.1)',
                          color: 'primary.main',
                          mb: 1
                        }}
                      />
                    ))}
                  </Stack>

                  <Typography 
                    variant="body2"
                    sx={{ 
                      color: 'grey.300',
                      lineHeight: 1.6
                    }}
                  >
                    {item.description}
                  </Typography>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>
      </Container>
    </Box>
  );
}
